<?php
require_once __DIR__ . '/config/config.php'; require_once __DIR__ . '/config/helpers.php'; require_login();
$pageTitle='Bills';$q=trim($_GET['q']??'');
$sql='SELECT b.*, f.name farmer_name, f.phone FROM bills b JOIN farmers f ON f.id=b.farmer_id';$params=[];if($q!==''){$sql.=' WHERE b.bill_number LIKE ? OR f.name LIKE ? OR f.phone LIKE ?';$params=["%$q%","%$q%","%$q%"];} $sql.=' ORDER BY b.id DESC';$s=$pdo->prepare($sql);$s->execute($params);$bills=$s->fetchAll();include __DIR__.'/includes/header.php';
?><div class="section-head"><form class="search" method="get"><input name="q" value="<?=e($q)?>" placeholder="Search bill number, farmer or phone" style="padding:11px;border:1px solid #d7ddd8;border-radius:7px"><button class="btn btn-light">Search</button></form><a class="btn btn-primary" href="bill_create.php">+ New Bill</a></div><div class="table-wrap"><table><thead><tr><th>Bill</th><th>Farmer</th><th>Date</th><th>Paddy</th><th>Gross</th><th>Payment</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($bills as $b):?><tr><td><strong><?=e($b['bill_number'])?></strong></td><td><?=e($b['farmer_name'])?></td><td><?=e(date('d M Y',strtotime($b['bill_date'])))?></td><td><?=e($b['paddy_type'])?></td><td><?=number_format($b['gross_weight_kg'],2)?> kg</td><td><?=money($b['total_amount'])?></td><td><span class="badge <?=$b['status']==='Paid'?'badge-paid':'badge-due'?>"><?=e($b['status'])?></span></td><td><a class="btn btn-light" href="bill_view.php?id=<?=$b['id']?>">View</a></td></tr><?php endforeach;?><?php if(!$bills):?><tr><td colspan="8" class="empty">No bills found.</td></tr><?php endif;?></tbody></table></div><?php include __DIR__.'/includes/footer.php'; ?>
